118 |     private long countUpdatedColumn(String sql) {
119 |         // UPDATE book SET isbn = ?, title = ? WHERE id = ?
120 |         int setIndex = sql.toLowerCase().indexOf("set");
121 |         int whereIndex = sql.toLowerCase().indexOf("where");
122 |         whereIndex = whereIndex > -1 ? whereIndex : sql.length();
123 | 
124 |         String sqlSetClause = sql.substring(setIndex, whereIndex);
125 |         return countUnquotedEquals(sqlSetClause);
126 |     }
