130 |      *  - "SET isbn = ?, title = ? " returns 2
131 |      *  - "SET isbn = '123', title = '1 + 1 = 0' " returns 2
132 |      */
133 |     private long countUnquotedEquals(String setClause) {
134 |         boolean inQuote = false;
135 |         long equalCounter = 0;
136 |         for (char c : setClause.toCharArray()) {
137 |             if (c == '\'') {
138 |                inQuote = !inQuote;
139 |             }
140 |             if (!inQuote && c == '=') {
141 |                 equalCounter++;
142 |             }
143 |         }
144 |         return equalCounter;
