34 |    @SuppressWarnings("unchecked")
35 |    private static SqlFormatter buildSqlFormatterBasedOnHibernate() {
36 |        try {
37 |            Class<? extends Enum> formatStyleClass = retrieveHibernateFormatStyleClass();
38 |            Method getFormatterMethod = formatStyleClass.getDeclaredMethod("getFormatter", null);
39 |            Enum formatStyleBasic = Enum.valueOf(formatStyleClass, "BASIC");
40 |            Object basicFormatter = getFormatterMethod.invoke(formatStyleBasic, null);
41 | 
42 |            Enum formatStyleDdl = Enum.valueOf(formatStyleClass, "DDL");
43 |            Object ddlFormatter = getFormatterMethod.invoke(formatStyleDdl, null);
44 | 
45 |            SqlFormatterBasedOnHibernate sqlFormatterBasedOnHibernate = new SqlFormatterBasedOnHibernate();
46 |            sqlFormatterBasedOnHibernate.basicFormatter = basicFormatter;
47 |            sqlFormatterBasedOnHibernate.ddlFormatter = ddlFormatter;
48 | 
49 |            sqlFormatterBasedOnHibernate.formatMethod = retrieveFormatOfHibernateFormatterClass();
50 | 
51 |            return sqlFormatterBasedOnHibernate;
52 | 
53 |        } catch (Exception e) {
54 |            // QuickPerf can't automatically retrieve Hibernate formatters
55 |            // if Hibernate version is less than 4
56 |            return SqlFormatter.NONE;
57 |        }
58 |    }
