60 |     @SuppressWarnings("unchecked")
61 |     private static Class<? extends Enum> retrieveHibernateFormatStyleClass() throws ClassNotFoundException {
62 |         ClassLoader loader = SqlFormatterBasedOnHibernate.class.getClassLoader();
63 |         String formatStyleClassName = "org.hibernate.engine.jdbc.internal.FormatStyle";
64 |         return (Class<? extends Enum>) loader.loadClass(formatStyleClassName);
65 |     }
